/* ════════════════════════════════════════════════════════════════════════════════════════════════
   WARM REPLY ASSISTANT — the Inbox's "Research & draft reply" row (2026-09-25).

   ⛔ IT NEVER SENDS. It asks warm-lead-reply for TEXT and hands it to `onDraft`, which puts it in
      the composer. Paul edits it and presses the composer's own Send. This component has no send
      path, no template picker and no call to send-whatsapp-message (scripts/warm-lead-reply.test.ts
      fails the build if one appears).

   Button states (Paul, 2026-10-11: BOTH BUTTONS ALWAYS SHOW, in every stage of the conversation):
     · "Draft reply"      — always. Stale research is refreshed first (as before); NO research is not fetched:
                            the draft is written from what we hold (the conversation, the audit if any) and
                            says "No audit yet, so no site issues included." when there was nothing to go on.
     · "Refresh research" — always. With no research saved it STARTS it (reads the site), then drafts.
     · after a draft      → "Regenerate" joins them (same research, no site fetch).
   Progress reads "Researching site…" → "Analysing…" → "Draft ready".

   ⛔ THE OLD WARM-ONLY GATE IS GONE (it hid the buttons on "HOOK NOT SENT" — Safety First Electrical,
      2026-10-11). The stage (src/lib/warmStage.ts) is still shown as a quiet label and the server still tells
      the model whether the hook has gone, so a draft before the hook may name the search, and one after it
      never repeats it.

   Mounted per conversation (keyed by it in the Inbox), so a draft or its "why" can never follow Paul
   into someone else's thread.
   ════════════════════════════════════════════════════════════════════════════════════════════════ */
import { LeadAiResultChips } from '@/components/LeadAiResultChips';
import { useEffect, useState, type ReactNode } from 'react';
import { AlertTriangle, Check, ChevronDown, Loader2, RefreshCw, Sparkles } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { invokeEdge, edgeErrorMessage } from '@/lib/edgeInvoke';
import { SALES_FACT_LABELS, SALES_FACT_KEYS, PRIMARY_MISSING_PROBLEM, type SalesFacts } from '@/lib/warmReply';
import { WARM_STAGE_LABELS, type WarmStage } from '@/lib/warmStage';
import { cn } from '@/lib/utils';

type Freshness = 'none' | 'fresh' | 'stale' | 'website_changed' | 'failed';
type Phase = 'idle' | 'researching' | 'analysing' | 'ready' | 'error';

interface ResearchSummary {
  generatedAt: string;
  status: string;
  technicallyClean: boolean;
  strongestFindings: Array<{ id: string; title: string; source: string; strength: number }>;
  warnings: string[];
  sourcesRead: number;
  timings?: { researchMs: number };
}

interface StatusResponse { ok: true; freshness: Freshness; has_website: boolean; research: ResearchSummary | null; sales_facts: SalesFacts }
interface ResearchResponse { ok: true; plan: string; research: ResearchSummary | null; ms: number }
interface FindingCard { id: string; title: string; evidence: string[]; source: string; score: number; used: boolean; required?: boolean }
interface DraftWhy {
  questionType: string;
  latestInbound?: { text: string } | null;
  primaryFinding?: FindingCard | null;
  secondaryFindings?: FindingCard[];
  strongNotUsed?: FindingCard[];
  alreadyMentioned?: string[];
  researchSources?: string[];
  aiSearchContext?: string | null;
  proposedSolution?: string;
  websiteOwnership?: string;
  finalQuestion?: string;
  noFindingNote?: string | null;
  questionSummary: string | null;
  detectedByRules: string[];
  findingsUsed: Array<{ id: string; title: string; source: string }>;
  research: { generatedAt: string; status: string; sourceCrawlAt: string | null; technicallyClean: boolean; warnings: string[] } | null;
  audit: { createdAt: string | null; named: number | null; total: number | null; namedEverywhere: boolean } | null;
  askedOwnership: boolean;
  ownershipAlreadyKnown: boolean;
  reportUrlAllowed: boolean;
  salesFacts: SalesFacts;
  factsRejected: string[];
  problems: string[];
  warnings: string[];
  operatorNote: string | null;
  usedFallback: boolean;
  timings: { generationMs: number; totalMs: number; researchMs: number | null };
  /** "No audit yet, so no site issues included." — set when the draft had nothing about their site to go on. */
  siteNote?: string | null;
}
interface DraftResponse { ok: true; reply: string; why: DraftWhy }

const QUESTION_LABELS: Record<string, string> = {
  price: 'Asked the price', how_it_works: 'Asked how it works', existing_provider: 'Already has a provider',
  show_changes: 'Asked what we’d change', tell_me_more: 'Wants more info', call_request: 'Asked for a call',
  ownership_answer: 'Answered about the site', not_interested: 'Not interested', other: 'General reply',
};

const day = (iso: string | null | undefined) => {
  if (!iso) return 'unknown date';
  try { return new Date(iso).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }); } catch { return iso; }
};
const secs = (ms: number | null | undefined) => (ms == null ? '—' : `${(ms / 1000).toFixed(1)}s`);

export interface WarmReplyAssistantProps {
  leadId: string;
  phone: string;
  /** The Meta 24h window, from the conversation's newest inbound message. */
  windowOpen: boolean;
  /** Where the conversation is in the funnel (warmStage over this thread). Only `warm` gets the button. */
  stage: WarmStage;
  /** Readable text for our own outbound template messages, by message id (context for the model). */
  getReadable: () => Record<string, string>;
  /** What is in the reply box now. A draft never silently replaces Paul's own typing. */
  getComposerText: () => string;
  /** Put the draft into the composer. The ONLY thing this component does with a draft. */
  onDraft: (text: string) => void;
}

export function WarmReplyAssistant({ leadId, phone, windowOpen, stage, getReadable, getComposerText, onDraft }: WarmReplyAssistantProps) {
  const [freshness, setFreshness] = useState<Freshness | null>(null);
  const [phase, setPhase] = useState<Phase>('idle');
  const [error, setError] = useState<string | null>(null);
  const [why, setWhy] = useState<DraftWhy | null>(null);
  const [lastReply, setLastReply] = useState<string | null>(null);
  const [variant, setVariant] = useState(0);
  const [whyOpen, setWhyOpen] = useState(false);

  /* The saved-research state decides the label. A read of our own table — no fetch, no model. */
  useEffect(() => {
    if (!windowOpen) return;
    let live = true;
    invokeEdge<StatusResponse>('warm-lead-reply', { action: 'status', lead_id: leadId, phone })
      .then((s) => { if (live) setFreshness(s.freshness); })
      .catch(() => { if (live) setFreshness('none'); });
    return () => { live = false; };
  }, [leadId, phone, windowOpen]);

  if (!windowOpen) {
    return (
      <p className="flex items-center gap-1 text-[11px] text-muted-foreground">
        <AlertTriangle className="h-3 w-3 shrink-0 text-amber-500" />
        Research &amp; draft reply needs the 24h window — only an approved Meta template can be sent now.
      </p>
    );
  }

  const busy = phase === 'researching' || phase === 'analysing';

  const run = async (mode: 'draft' | 'refresh' | 'regenerate') => {
    if (busy) return;
    /* Ask only when the box holds something Paul wrote — our own untouched draft is replaced freely. */
    const current = getComposerText().trim();
    if (current && current !== (lastReply ?? '').trim() && !window.confirm('Replace what is in the reply box with a new draft?')) return;
    setError(null);
    try {
      /* Regenerate NEVER asks for research — it reuses the saved record. Refresh always does. A first
         draft asks only when nothing fresh is saved, and the server still reuses what it can. */
      /* No research saved (none / failed) → Draft reply does NOT fetch the site: it drafts from what we hold.
         Refresh research is the button that starts it. Stale or changed research is refreshed first, as before. */
      if (mode === 'refresh' || (mode === 'draft' && (freshness === 'stale' || freshness === 'website_changed'))) {
        setPhase('researching');
        await invokeEdge<ResearchResponse>('warm-lead-reply', { action: 'research', lead_id: leadId, phone, refresh: mode === 'refresh' });
        setFreshness('fresh');
      }
      setPhase('analysing');
      const nextVariant = mode === 'regenerate' ? variant + 1 : 0;
      const d = await invokeEdge<DraftResponse>('warm-lead-reply', {
        action: 'draft', lead_id: leadId, phone, readable: getReadable(),
        variant: nextVariant, avoid: mode === 'regenerate' ? lastReply : null,
      });
      onDraft(d.reply);
      setWhy(d.why);
      setLastReply(d.reply);
      setVariant(nextVariant);
      setPhase('ready');
    } catch (e) {
      setError(edgeErrorMessage(e, 'Could not draft a reply.'));
      setPhase('error');
    }
  };

  const hasDraft = lastReply !== null;
  const mainTitle = freshness === 'fresh'
    ? 'Draft a reply from the saved research — nothing is sent'
    : freshness === 'stale' || freshness === 'website_changed'
      ? 'Re-read their site, then draft a reply — nothing is sent'
      : 'Draft a reply from the conversation (no site research saved yet) — nothing is sent';

  return (
    <div className="space-y-1.5">
      <div className="flex flex-wrap items-center gap-1.5">
        <Button type="button" variant="outline" size="sm" className="h-7 gap-1 text-xs" disabled={busy}
          onClick={() => void run('draft')} title={mainTitle} data-testid="warm-draft-reply">
          {busy ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5 text-violet-600 dark:text-violet-300" />}
          Draft reply
        </Button>
        {hasDraft && (
          <Button type="button" variant="outline" size="sm" className="h-7 gap-1 text-xs" disabled={busy}
            onClick={() => void run('regenerate')} title="Write another version from the same saved research (does not re-read the site)">
            <RefreshCw className="h-3.5 w-3.5" /> Regenerate
          </Button>
        )}
        <Button type="button" variant="ghost" size="sm" className="h-7 px-2 text-xs text-muted-foreground" disabled={busy}
          onClick={() => void run('refresh')} title={freshness === 'fresh' || freshness === 'stale' ? 'Re-read their website, then draft again' : 'Read their website for the first time, then draft'}
          data-testid="warm-refresh-research">
          Refresh research
        </Button>
        <span className="text-[10px] uppercase tracking-wide text-muted-foreground/70" title="Where the conversation is">{WARM_STAGE_LABELS[stage]}</span>
        <span className="text-[11px] text-muted-foreground" aria-live="polite">
          {phase === 'researching' && 'Researching site…'}
          {phase === 'analysing' && 'Analysing…'}
          {phase === 'ready' && <span className="inline-flex items-center gap-1 text-teal-700 dark:text-teal-300"><Check className="h-3 w-3" /> Draft ready — review, edit, then send</span>}
        </span>
        {why && (
          <button type="button" onClick={() => setWhyOpen((o) => !o)} aria-expanded={whyOpen}
            className="ml-auto inline-flex items-center gap-0.5 text-[11px] text-muted-foreground hover:text-foreground">
            Why this reply? <ChevronDown className={cn('h-3 w-3 transition-transform', whyOpen && 'rotate-180')} />
          </button>
        )}
      </div>
      {error && <p className="text-[11px] text-destructive">{error}</p>}
      {why?.siteNote && <p className="text-[11px] text-muted-foreground" data-testid="warm-site-note">{why.siteNote}</p>}
      {why && why.problems.length > 0 && !whyOpen && (
        <p className="flex items-start gap-1 text-[11px] text-amber-700 dark:text-amber-300">
          <AlertTriangle className="mt-0.5 h-3 w-3 shrink-0" />
          <span><span className="font-semibold">CHECK THIS DRAFT</span> — {why.problems.includes(PRIMARY_MISSING_PROBLEM) ? PRIMARY_MISSING_PROBLEM : why.problems[0]}</span>
        </p>
      )}
      {why && whyOpen && <WhyPanel why={why} leadId={leadId} />}
    </div>
  );
}

function WhyPanel({ why, leadId }: { why: DraftWhy; leadId: string }) {
  const facts = SALES_FACT_KEYS.filter((k) => why.salesFacts?.[k]);
  return (
    <div className="space-y-1.5 rounded-xl bg-muted/40 px-3 py-2 text-[11px] leading-snug ring-1 ring-inset ring-border/50">
      <p className="text-muted-foreground">For you only — none of this is sent. Nothing has been sent.</p>
      <LeadAiResultChips leadId={leadId} />
      <Row label="Question detected">
        {why.latestInbound?.text ? `“${why.latestInbound.text}” · ` : ''}{QUESTION_LABELS[why.questionType] ?? why.questionType}
      </Row>
      {why.aiSearchContext && <Row label="AI search context">{why.aiSearchContext}</Row>}
      {why.primaryFinding ? (
        <>
          <Row label="Primary issue" tone={why.primaryFinding.used ? undefined : why.primaryFinding.required ? 'bad' : 'warn'}>
            {why.primaryFinding.title} · {why.primaryFinding.used ? 'used' : why.primaryFinding.required ? 'NOT used' : 'not used (not needed for this message)'}
          </Row>
          {why.primaryFinding.evidence.length > 0 && <Row label="Evidence">{why.primaryFinding.evidence.join(' / ')}</Row>}
        </>
      ) : (
        <Row label="Primary issue">{why.noFindingNote ?? 'None strong enough to lead with, nothing was invented'}</Row>
      )}
      {why.secondaryFindings && why.secondaryFindings.length > 0 && (
        <Row label="Secondary findings">{why.secondaryFindings.map((f) => `${f.title}${f.used ? ' (used)' : ''}`).join(' · ')}</Row>
      )}
      {why.strongNotUsed && why.strongNotUsed.length > 0 && (
        <Row label="Strong findings not used" tone="warn">{why.strongNotUsed.map((f) => f.title).join(' · ')}</Row>
      )}
      {why.alreadyMentioned && why.alreadyMentioned.length > 0 && (
        <Row label="Already told them">{why.alreadyMentioned.join(' · ')}</Row>
      )}
      {why.proposedSolution && <Row label="Proposed solution">{why.proposedSolution}</Row>}
      {why.websiteOwnership && <Row label="Website ownership">{why.websiteOwnership}</Row>}
      {why.finalQuestion && <Row label="Final question">{why.finalQuestion}</Row>}
      <Row label="Research source">
        {[why.primaryFinding?.source, ...(why.researchSources ?? [])].filter((x, i, a) => x && a.indexOf(x) === i).join(' · ') || '—'}
      </Row>
      <Row label="Research">
        {why.research
          ? `${day(why.research.generatedAt)} · ${why.research.status}${why.research.technicallyClean ? ' · no technical fault found' : ''}`
          : 'None saved — the site was not mentioned'}
      </Row>
      {why.audit && (
        <Row label="AI check">
          {why.audit.namedEverywhere ? 'Named on every engine' : why.audit.total ? `Named ${why.audit.named ?? 0} of ${why.audit.total}` : 'No counts'} · {day(why.audit.createdAt)}
        </Row>
      )}
      <Row label="Ownership">
        {why.ownershipAlreadyKnown ? 'Already answered — not asked again' : why.askedOwnership ? 'Asked (the research gave a reason)' : 'Not asked'}
        {' · '}Report link {why.reportUrlAllowed ? 'allowed' : 'not included'}
      </Row>
      {facts.length > 0 && (
        <Row label="They’ve said">
          {facts.map((k) => `${SALES_FACT_LABELS[k]}: ${why.salesFacts[k]!.value} (“${why.salesFacts[k]!.quote}”)`).join(' · ')}
        </Row>
      )}
      {why.research?.warnings?.length ? <Row label="Research notes">{why.research.warnings.join(' ')}</Row> : null}
      {why.problems.length > 0 && <Row label="Check" tone="bad">{why.problems.join(' ')}</Row>}
      {why.warnings.length > 0 && <Row label="Worth a look" tone="warn">{why.warnings.join(' ')}</Row>}
      {why.operatorNote && <Row label="Note">{why.operatorNote}</Row>}
      <Row label="Timing">
        Research {secs(why.timings.researchMs)} · draft {secs(why.timings.generationMs)}{why.usedFallback ? ' · model unavailable, rule-built draft' : ''}
      </Row>
    </div>
  );
}

function Row({ label, children, tone }: { label: string; children: ReactNode; tone?: 'bad' | 'warn' }) {
  return (
    <p className={cn(tone === 'bad' && 'text-destructive', tone === 'warn' && 'text-amber-700 dark:text-amber-300')}>
      <span className="font-medium text-foreground">{label}: </span>{children}
    </p>
  );
}
